import {bundledVisualHarness} from './helpers/bundled-visual.js';
import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import vm from 'node:vm';
import {bundledVisualBindings as pins,bundledVisualReviewSha256 as reviewSHA,validateBundledVisual} from '../src/lib/bundled-visuals.js';import {bindVerifiedVisuals} from '../src/lib/verified-visuals.js';
const review=JSON.parse(readFileSync('../../server/fia/preparation/bundled-visual-review.json')),origin='https://fia.test',hash=b=>createHash('sha256').update(b).digest('hex'),rowsFor=id=>review.rows.filter(r=>r.packId===id),manifestFor=(f,g=reviewSHA)=>({packId:f.visualPublication.packId,presentationRevision:f.visualPublication.presentationRevision,deliveryRevision:g});
test('all46 qualified bundled online and saved planner descriptors bind in either order',async()=>{
 for(const pin of pins){const online={...pin,deliveryRevision:reviewSHA},saved={...online,selectedSize:'prepared'},p=pin.visualPublication,row=rowsFor(p.packId).find(r=>r.assetId===p.assetId);
  for(const files of [[online,saved],[saved,online]])assert.equal((await bindVerifiedVisuals(files,{id:p.packId,revision:p.presentationRevision},{[p.assetId]:row.asset},reviewSHA)).get(p.assetId).sha256,pin.sha256);
 }
});
test('saved planner annotation cannot hide bundled identity, route, rights or pixel changes',async()=>{
 const online={...pins[0],deliveryRevision:reviewSHA},p=online.visualPublication,row=rowsFor(p.packId).find(r=>r.assetId===p.assetId);
 for(const patch of [{sha256:'f'.repeat(64)},{bytes:online.bytes+1},{deliveryURL:online.deliveryURL+'x'},{visualPublication:{...p,pixelsSha256:'f'.repeat(64)}},{visualPublication:{...p,rightsRecordSha256:'f'.repeat(64)}},{visualPublication:{...p,recipeSha256:'f'.repeat(64)}}])await assert.rejects(bindVerifiedVisuals([online,{...online,selectedSize:'prepared',...patch}],{id:p.packId,revision:p.presentationRevision},{[p.assetId]:row.asset},reviewSHA));
});
test('all46 exact current authored assets bind; only approved default8 permit null source evidence',async()=>{assert.equal(pins.length,46);let defaults=0;for(const pin of pins){const f={...pin,deliveryRevision:reviewSHA},p=f.visualPublication,row=rowsFor(p.packId).find(r=>r.assetId===p.assetId);assert.equal((await bindVerifiedVisuals([f],{id:p.packId,revision:p.presentationRevision},{[p.assetId]:row.asset},reviewSHA)).get(p.assetId).sha256,f.sha256);if(p.sourceEvidenceSha256===null){defaults++;assert.equal(p.bindingKind,'approved-default');}else assert.equal(p.bindingKind,'canonical-source');}assert.equal(defaults,8);});
test('wrong rights/review/source/asset/content/recipe/current revision and remote default exceptions fail closed',async()=>{const f={...pins[0],deliveryRevision:reviewSHA},p=f.visualPublication,m=manifestFor(f),row=rowsFor(p.packId).find(r=>r.assetId===p.assetId);for(const patch of [{rightsRecordSha256:'f'.repeat(64)},{reviewSha256:'f'.repeat(64)},{assetSha256:'f'.repeat(64)},{sourceEvidenceSha256:null},{assetId:'a999'},{bindingKind:'approved-default'},{custody:'publisher-original'},{recipeSha256:'f'.repeat(64)}])assert.throws(()=>validateBundledVisual({...f,visualPublication:{...p,...patch}},m));for(const patch of [{sha256:'f'.repeat(64)},{deliveryURL:'https://publisher.invalid/raw'},{bytes:f.bytes+1},{variants:{}},{deliveryRevision:'f'.repeat(64)}])assert.throws(()=>validateBundledVisual({...f,...patch},m));await assert.rejects(bindVerifiedVisuals([f],{id:p.packId,revision:p.presentationRevision},{[p.assetId]:{...row.asset,title:'different'}},reviewSHA));await assert.rejects(bindVerifiedVisuals([f],{id:p.packId,revision:'f'.repeat(64)},{[p.assetId]:row.asset},reviewSHA));const def=pins.find(f=>f.visualPublication.bindingKind==='approved-default');await assert.rejects(bindVerifiedVisuals([{...def,deliveryRevision:reviewSHA,visualPublication:{...def.visualPublication,schema:'fia-verified-visual@1'}}],{id:def.visualPublication.packId,revision:def.visualPublication.presentationRevision},{[def.visualPublication.assetId]:rowsFor(def.visualPublication.packId).find(r=>r.assetId===def.visualPublication.assetId).asset},reviewSHA));});
for(const classic of [false,true])test(`actual static manifest → SW view/save/offline ${classic?'preserves classic audio generation':'uses review generation'}`,async()=>{const h=bundledVisualHarness({classic}),p=h.pin.visualPublication,status=await h.message('MEDIA_STATUS',{revision:p.presentationRevision});assert.equal(status.ok,true,JSON.stringify(status));const f=status.files.find(f=>f.visualPublication);assert.equal(f.deliveryRevision,classic?'a'.repeat(64):reviewSHA);assert.equal(f.visualPublication.reviewSha256,reviewSHA);assert.equal(f.deliveryURL,h.pin.deliveryURL);if(classic)assert.equal(status.files.find(f=>f.group==='audio').deliveryRevision,'a'.repeat(64));const view=await h.message('MEDIA_PLAY',{revision:p.presentationRevision,deliveryRevision:f.deliveryRevision,path:f.path,requestId:'explicit-view'});assert.equal(view.ok,true,JSON.stringify(view));assert.equal(hash(new Uint8Array(view.bytes)),f.sha256);const save=await h.message('DOWNLOAD_START',{selection:'all',sizes:{image:'prepared',...(classic?{audio:'prepared'}:{})}});assert.equal(save.ok,true,JSON.stringify(save));assert.equal(save.saved,true);h.offline(true);const saved=await h.message('DOWNLOAD_STATUS');assert.equal(saved.saved,true,JSON.stringify(saved));assert.equal((await bindVerifiedVisuals(saved.active.files,{id:p.packId,revision:p.presentationRevision},Object.fromEntries(rowsFor(p.packId).map(r=>[r.assetId,r.asset])),f.deliveryRevision)).get(p.assetId).path,f.path);const cached=await h.message('MEDIA_PLAY',{revision:p.presentationRevision,deliveryRevision:f.deliveryRevision,path:f.path,requestId:'cold-offline'});assert.equal(cached.ok,true,JSON.stringify(cached));assert.equal(hash(new Uint8Array(cached.bytes)),f.sha256);assert.ok(h.calls.every(u=>!u.includes('publisher')&&!u.includes('s3.amazonaws')));});
test('actual SW rejects corrupt static bytes before saved state',async()=>{const h=bundledVisualHarness({corrupt:true}),p=h.pin.visualPublication;assert.equal((await h.message('MEDIA_PLAY',{revision:p.presentationRevision,deliveryRevision:reviewSHA,path:h.pin.path,requestId:'corrupt'})).ok,false);assert.equal((await h.message('DOWNLOAD_START',{selection:'all',sizes:{image:'prepared'}})).ok,false);});
test('worker merge refuses wrong base review, mixed file generation, duplicate path and malformed/refused discovery',async()=>{const h=bundledVisualHarness(),f={...h.pin,deliveryRevision:reviewSHA},p=f.visualPublication,value={schema:'fia-bundled-visual-manifest@1',custody:'bundled-static',packId:p.packId,presentationRevision:p.presentationRevision,deliveryRevision:reviewSHA,files:[f]};h.context.base={...manifestFor(f),files:[]};for(const bad of [{...value,deliveryRevision:'f'.repeat(64)},{...value,files:[{...f,deliveryRevision:'f'.repeat(64)}]},{...value,files:[f,f]},{...value,files:[{...f,visualPublication:{...p,rightsRecordSha256:'f'.repeat(64)}}]},{...value,packId:'spa.MRK-1-1-13'}]){h.context.request=async()=>Response.json(bad);await assert.rejects(vm.runInContext('mergeBundledVisuals(base,request)',h.context));}h.context.request=async()=>new Response('invalid');await assert.rejects(vm.runInContext('mergeBundledVisuals(base,request)',h.context));h.context.request=async()=>new Response('',{status:403});await assert.rejects(vm.runInContext('mergeBundledVisuals(base,request)',h.context));});
